import {finite} from './expert-stats.mjs?v=20261102-expert1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=(n,d=2)=>finite(n)?Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d}):'未提供';
export function plot(series,{unit='',xLabel='日期',marker=null,source='',xKind='date',height=250}={}){const width=680,p={l:64,r:15,t:24,b:42},points=series.flatMap(s=>s.points).filter(r=>finite(r.x)&&finite(r.y));if(!points.length)return '<div class="empty">缺少合规数值，未生成曲线或结论</div>';const xs=points.map(p=>Number(p.x)),ys=series.flatMap(s=>s.points.flatMap(p=>[p.y,p.low,p.high])).filter(finite).map(Number);let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);if(minX===maxX)maxX++;const pad=Math.max(1e-6,(maxY-minY)*.1);minY-=pad;maxY+=pad;const x=v=>p.l+(v-minX)/(maxX-minX)*(width-p.l-p.r),y=v=>height-p.b-(v-minY)/(maxY-minY)*(height-p.t-p.b);const parts=a=>{const out=[];let part=[];for(const q of a){if(finite(q.x)&&finite(q.y)){part.push(q);}else if(part.length){out.push(part);part=[];}}if(part.length)out.push(part);return out;};return `<div class="expert-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}${s.dash?'（虚线）':'（实线）'}</span>`).join('')}</div><svg class="expert-plot" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(series.map(s=>s.name).join('、'))}"><text x="${p.l}" y="13">${esc(unit)}</text>${Array.from({length:4},(_,i)=>{const v=minY+(maxY-minY)*i/3;return `<line x1="${p.l}" x2="${width-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e9e6e1"/><text x="${p.l-7}" y="${y(v)+3}" text-anchor="end">${fmt(v,2)}</text>`;}).join('')}${marker!==null&&marker>=minX&&marker<=maxX?`<line x1="${x(marker)}" x2="${x(marker)}" y1="${p.t}" y2="${height-p.b}" stroke="#ac2530" stroke-dasharray="4 4"/><text x="${x(marker)+4}" y="25">措施实施</text>`:''}${series.map(s=>parts(s.points).map(a=>{const bands=a.filter(v=>finite(v.low)&&finite(v.high));return `${bands.length>1?`<polygon points="${[...bands.map(v=>`${x(v.x)},${y(v.low)}`),...bands.slice().reverse().map(v=>`${x(v.x)},${y(v.high)}`)].join(' ')}" fill="${s.color}" opacity=".13"><title>浅色带：${esc(s.bandName??'条件95%区间')}</title></polygon>`:''}<polyline points="${a.map(v=>`${x(v.x)},${y(v.y)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2" ${s.dash?'stroke-dasharray="6 4"':''}/>`;}).join('')).join('')}<text x="${p.l}" y="${height-21}">${esc(xKind==='date'?new Date(minX*864e5).toISOString().slice(0,10):fmt(minX))}</text><text x="${width-p.r}" y="${height-21}" text-anchor="end">${esc(xKind==='date'?new Date(maxX*864e5).toISOString().slice(0,10):fmt(maxX))}</text><text x="${width/2}" y="${height-3}" text-anchor="middle">${esc(xLabel)}</text></svg><div class="small-note">${esc(source)} · 缺失数据断线；浅色带的类型以图例说明为准。</div>`;}
export function connectivityMap(wells,traces){const ids=[...new Set(traces.flatMap(t=>[t.injector,t.producer]))];if(!ids.length)return '<div class="empty">载入示踪剂井层对后生成连通图；也可上传原始解释图。</div>';const actual=ids.every(id=>wells.some(w=>w.well_id===id&&finite(w.x_m)&&finite(w.y_m))),positions=ids.map((id,i)=>{const w=wells.find(w=>w.well_id===id);return {id,x:actual?Number(w.x_m):i===0?80:400,y:actual?Number(w.y_m):(i===0?160:50+(i-1)*65)};});const xs=positions.map(p=>p.x),ys=positions.map(p=>p.y),sx=v=>55+(v-Math.min(...xs))/Math.max(1,Math.max(...xs)-Math.min(...xs))*570,sy=v=>45+(Math.max(...ys)-v)/Math.max(1,Math.max(...ys)-Math.min(...ys))*270;return `<svg class="expert-map" viewBox="0 0 680 370" role="img" aria-label="示踪剂井间及层间连通图"><defs><marker id="expert-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#6c8d7e"/></marker></defs>${traces.map((t,i)=>{const a=positions.find(p=>p.id===t.injector),b=positions.find(p=>p.id===t.producer),cross=t.layerFrom&&t.layerTo&&t.layerFrom!==t.layerTo,color=t.firstArrival===null?'#a9a9ad':cross?'#8753a0':t.fast?'#b02a35':'#397e68';return `<line x1="${sx(a.x)}" y1="${sy(a.y)}" x2="${sx(b.x)}" y2="${sy(b.y)}" stroke="${color}" stroke-width="${t.firstArrival===null?1:3}" stroke-dasharray="${cross||t.firstArrival===null?'6 5':'none'}" marker-end="url(#expert-arrow)"><title>${esc(t.injector+' '+t.layerFrom+' → '+t.producer+' '+t.layerTo)}；首次见剂${fmt(t.firstArrival)}天；回收率${fmt(t.recoveryFraction===null?null:t.recoveryFraction*100)}%</title></line><text x="${(sx(a.x)+sx(b.x))/2}" y="${(sy(a.y)+sy(b.y))/2-8-i%2*12}" fill="${color}">${esc(t.layerFrom??'?')}→${esc(t.layerTo??'?')} · ${t.firstArrival===null?'未检出':fmt(t.firstArrival)+'天'}</text>`;}).join('')}${positions.map(p=>`<circle cx="${sx(p.x)}" cy="${sy(p.y)}" r="8" fill="${traces.some(t=>t.injector===p.id)?'#b02a35':'#397e68'}"/><text x="${sx(p.x)+12}" y="${sy(p.y)+4}">${esc(p.id)}</text>`).join('')}<text x="35" y="356">${actual?'按上传局部坐标绘制；连线代表检出路径证据，不是裂缝几何。':'拓扑示意布局，非实际井位；请上传wells坐标表。'}</text></svg><div class="expert-legend"><span style="color:#397e68">绿色：见剂路径</span><span style="color:#b02a35">红色：达到早见剂阈值</span><span style="color:#8753a0">紫色虚线：跨层迁移候选</span><span>灰色虚线：观测窗未检出</span></div>`;}
export function microMap(m,{depth=false,wells=[]}={}){if(!m.available)return '<div class="empty">尚无可定位的微地震事件</div>';const a=m.events,key=depth?'z_m':'y_m',ws=wells.filter(w=>finite(w.x_m)&&finite(depth?w.depth_m:w.y_m)).map(w=>({...w,[key]:Number(depth?w.depth_m:w.y_m),x_m:Number(w.x_m)})),vals=k=>[...a,...ws].map(r=>r[k]),loX=Math.min(...vals('x_m')),hiX=Math.max(...vals('x_m')),loY=Math.min(...vals(key)),hiY=Math.max(...vals(key)),sx=v=>55+(v-loX)/Math.max(1,hiX-loX)*565,sy=v=>35+(depth?(v-loY):(hiY-v))/Math.max(1,hiY-loY)*240;return `<svg class="expert-map" viewBox="0 0 680 330" role="img" aria-label="微地震${depth?'深度剖面':'平面'}事件图">${!depth&&m.polygon.length>2?`<polygon points="${m.polygon.map(r=>sx(r.x_m)+','+sy(r.y_m)).join(' ')}" fill="#ead8ba" stroke="#b68c50" opacity=".5"/>`:''}${depth?m.layers.filter(l=>finite(l.top_m)&&finite(l.bottom_m)).map(l=>`<line x1="55" x2="620" y1="${sy(Number(l.top_m))}" y2="${sy(Number(l.top_m))}" stroke="#477ca6" stroke-dasharray="4 5"/><text x="55" y="${sy(Number(l.top_m))-5}">${esc(l.layer)}层顶 ${fmt(l.top_m)}米</text>`).join(''):''}${ws.map(w=>`<circle cx="${sx(w.x_m)}" cy="${sy(w[key])}" r="5" fill="#477ca6"/><text x="${sx(w.x_m)+8}" y="${sy(w[key])+4}">${esc(w.well_id)}</text>`).join('')}${a.slice(0,1500).map(r=>`<circle cx="${sx(r.x_m)}" cy="${sy(r[key])}" r="2.4" fill="#b02a35" opacity=".65"><title>局部坐标${r.x_m.toFixed(1)},${r.y_m.toFixed(1)},${r.z_m.toFixed(1)}米</title></circle>`).join('')}<text x="55" y="300">X ${fmt(loX,0)}—${fmt(hiX,0)}米；${depth?'深度向下':'Y'} ${fmt(loY,0)}—${fmt(hiY,0)}米</text><text x="55" y="318">蓝点：上传井位；红点：微地震事件；${depth?'蓝虚线：层位界面':'金色：事件凸包'}。${a.length>1500?'预览前1500点，统计使用全部有效事件。':''}</text></svg>`;}
